function wordBreak(s: string, wordDict: string[]): boolean {
  const n = s.length;
  // Множество слов: проверка «есть ли кусок в словаре» без перебора массива
  const words = new Set(wordDict);

  // Состояние: dp[i] — можно ли разбить префикс s[0..i) на слова словаря
  const dp: boolean[] = new Array(n + 1).fill(false);
  // База: пустой префикс разбивается всегда (ноль слов)
  dp[0] = true;

  // Порядок: i по возрастанию — все dp[j] для j < i уже посчитаны
  for (let i = 1; i <= n; i++) {
    // Перебираем начало j последнего слова s[j..i)
    for (let j = 0; j < i; j++) {
      // Переход: префикс до j разбивается, а s[j..i) — слово из словаря
      if (dp[j] && words.has(s.slice(j, i))) {
        dp[i] = true;
        break; // одного способа достаточно
      }
    }
  }

  // Ответ: можно ли разбить всю строку
  return dp[n];
}

// Время: O(n³) — n² пар (j, i), срез строки за O(n); при n <= 300 это быстро
// Память: O(n + размер словаря)
